/*
 * Arithmetic mod 8191
 */
inline static int gf_sub(int a, int b) {
	a -= b;
	if (a < 0) a += 8191;
	return a;
}
inline static int gf_mul(int a, int b) {
	a *= b;
	a = (a & 8191) + (a >> 13);
	if (a >= 8191) a -= 8191;
	return a;
}
inline static int gf_addmul(int c, int a, int b) {
	a = c + a * b;
	a = (a & 8191) + (a >> 13);
	if (a >= 8191) a -= 8191;
	assert(a <= 8190);
	return a;
}

