// Laplacian matrix
static int gr_matrix[16][16];

[[gnu::noinline]] static uint32_t gr_solve(size_t n) {
	/*
	 * Count the number of spanning trees of the graph.
	 *
	 * In this solution we use Kirchoff's theorem.
	 */
	assert(n >= 2);
	assert(n <= 16);
	n--;

	/*
	 * We compute the determinant of gr_matrix, a n*n matrix.
	 *
	 * We use Gaussian elimination. The answer is small, so work in GF(8191).
	 */

	for (size_t i = 0; i < n; i++) {
		for (size_t j = 0; j < n; j++) {
			if (gr_matrix[i][j] < 0) {
				gr_matrix[i][j] += 8191;
			}
			assert(gr_matrix[i][j] >= 0);
			assert(gr_matrix[i][j] < 8191);
		}
	}

	int det = 1;
	for (size_t i = 0; i < n; i++) {
		if (gr_matrix[i][i] == 0) {
			size_t j;
			for (j = i + 1; j < n; j++) {
				if (gr_matrix[i][j] != 0) {
					break;
				}
			}
			// The determinant is nonzero.
			assert(j < n);
			for (size_t k = i; k < n; k++) {
				std::swap(gr_matrix[i][k], gr_matrix[j][k]);
			}
			det = -det;
		}
		int scale = gr_matrix[i][i];
		if (scale != 1) {
			det = gf_mul(det, scale);
			gr_matrix[i][i] = 1;
			scale = gf_inv(scale);
			for (size_t k = i + 1; k < n; k++) {
				gr_matrix[i][k] = gf_mul(gr_matrix[i][k], scale);
			}
		}
		for (size_t j = i + 1; j < n; j++) {
			scale = gr_matrix[j][i];
			if (scale == 0) continue;
			scale = 8191 - scale;
			gr_matrix[j][i] = 0;
			for (size_t k = i + 1; k < n; k++) {
				gr_matrix[j][k] = gf_addmul(gr_matrix[j][k], gr_matrix[i][k], scale);
			}
		}
	}

	return det;
}

inline static void gr_reset() {
	memset(gr_matrix, 0, sizeof(gr_matrix));
}

inline static void gr_edge(size_t a, size_t b) {
	assert(a != b);
	if (a >= 16 || b >= 16) return;
	gr_matrix[a][b]--;
	gr_matrix[b][a]--;
	gr_matrix[a][a]++;
	gr_matrix[b][b]++;
}

// (parent, rank) pairs
static std::pair<unsigned, unsigned> uf_parent[1 << 17];

static void uf_init(size_t n) {
	for (size_t i = 0; i < n; i++) {
		uf_parent[i] = std::make_pair(i, 0);
	}
}

static size_t uf_find(size_t i) {
	// Step 1: find root
	size_t j = i;
	while (true) {
		size_t k = uf_parent[j].first;
		if (k == j) break;
		j = k;
	}
	// Step 2: update path
	while(i != j) {
		size_t k = uf_parent[i].first;
		uf_parent[i].first = j;
		i = k;
	}
	return j;
}

static void uf_union(size_t a, size_t b) {
	a = uf_find(a);
	b = uf_find(b);
	if (a == b) return;
	if (uf_parent[a].second < uf_parent[b].second) {
		std::swap(a, b);
	} else if (uf_parent[a].second == uf_parent[b].second) {
		uf_parent[a].second++;
	}
	uf_parent[b].first = a;
}

struct Edge {
	unsigned tag, a, b;
};

inline bool operator<(Edge a, Edge b) noexcept {
	return a.tag < b.tag;
}

static Edge *edge_group(Edge *begin, Edge *end) {
	if (begin == end) {
		return nullptr;
	}
	unsigned tag = begin->tag;
	do {
		begin++;
	} while (begin < end && begin->tag == tag);
	return begin;
}

static unsigned part_vert[32];
static size_t part_n_vert;
static size_t part_mark(unsigned u) {
	for (size_t i = 0; i < part_n_vert; i++) {
		if (part_vert[i] == u) {
			return i;
		}
	}
	size_t i = part_n_vert++;
	part_vert[i] = u;
	return i;
}

static unsigned part_solve(Edge *begin, Edge *end) {
	// First update the edges to point to the input union-find components.
	for (Edge *e = begin; e < end; e++) {
		e->a = uf_find(e->a);
		e->b = uf_find(e->b);
		if (e->a == e->b) {
			// Loop edge. Remove.
			*e = *begin++;
		}
		// Do not merge components -- this will mess up the remaining edges.
	}
	// Instead, apply the edges now.
	for (const Edge *e = begin; e < end; e++) {
		uf_union(e->a, e->b);
	}

	// Label edges with connected component.
	for (Edge *e = begin; e < end; e++) {
		e->tag = uf_find(e->a);
		assert(e->tag == uf_find(e->b));
	}

	// Iterate over connected components.
	std::sort(begin, end);
	unsigned answer = 1;
	while (Edge *mid = edge_group(begin, end)) {
		for (Edge *e = begin; e < mid; e++) {
			gr_edge(part_mark(e->a), part_mark(e->b));
		}
		size_t n = part_n_vert;
		size_t m = mid - begin;
		assert(n >= 2);
		if (n < m + 1) {
			assert(n <= 16);
			answer *= gr_solve(n);
		} else {
			// The component is a tree. Nothing to do.
			assert(n == m + 1);
		}
		gr_reset();
		begin = mid;
		part_n_vert = 0;
	}
	return answer;
}

static Edge edges[1 << 20];
int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr);

	size_t n, m;
	std::cin >> n >> m;
	for (size_t i = 0; i < m; i++) {
		unsigned a, b, c;
		std::cin >> a >> b >> c;
		assert(1 <= a && a <= n);
		assert(1 <= b && b <= n);
		assert(a < b);
		edges[i] = Edge { c, a - 1, b - 1 };
	}
	assert(std::cin);

	Edge *begin = edges;
	Edge *end = begin + m;
	std::sort(begin, end);

	unsigned answer = 1;

	uf_init(n);
	while (Edge *mid = edge_group(begin, end)) {
		answer = (unsigned long long)answer * part_solve(begin, mid) % 1000000007;
		begin = mid;
	}

	std::cout << answer << '\n';

	return 0;
}
